args.sparql:
SELECT DISTINCT ?director ?directorLabel WHERE {
  dbr:The_Alster_Case (dbo:director|dbp:director) ?director .
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER (lang(?directorLabel) = 'en') }
}

SELECT DISTINCT ?deathPlace ?deathPlaceLabel WHERE {
  dbr:J._Charles_Haydon (dbo:deathPlace|dbp:deathPlace) ?deathPlace .
  OPTIONAL { ?deathPlace rdfs:label ?deathPlaceLabel . FILTER(lang(?deathPlaceLabel) = 'en') }
}

SELECT DISTINCT ?deathPlace ?deathPlaceLabel WHERE {
  dbr:J._Charles_Haydon (dbo:deathPlace|dbp:deathPlace) ?deathPlace .
  OPTIONAL { ?deathPlace rdfs:label ?deathPlaceLabel . FILTER(lang(?deathPlaceLabel) = 'en') }
}

